import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> kota = Arrays.asList("Bogor", "Solo", "Bandung");
        long a = kota.stream().count();
        long b = kota.stream().filter(k -> k.startsWith("B")).count();
