import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> pesanan = Arrays.asList("kopi", "teh", "kopi", "susu");
        long semua = pesanan.stream().count();
        long kopi = pesanan.stream().filter(p -> p.equals("kopi")).count();
        System.out.println("Semua: " + semua);
        System.out.println("Kopi: " + kopi);
    }
}

